mapper.update:
update tlias.clazz

    name = #{name},room = #{room},begin_date = #{beginDate},end_date = #{endDate},master_id =
    #{masterId},update_time = #{updateTime},update_time = #{updateTime},
    subject = #{subject}

where tlias.clazz.id = #{id}

mapper.select:
select clazz.*, emp.name as master_name from clazz inner join emp on clazz.master_id = emp.id
and clazz.name like concat('%',#{name},'%') and clazz.end_date between #{begin} and #{end}
order by tlias.clazz.update_time desc
